    CONSTRAINT finance_invoice_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'open'::text, 'partially_paid'::text, 'paid'::text, 'overdue'::text, 'disputed'::text, 'credited'::text, 'void'::text]))),
